<template>
  <div class="office-page"><AppSidebar/><main class="main"><header><div><h2>{{z.title}}</h2><p>{{z.subtitle}}</p></div><el-button type="primary" size="small" @click="openDoc">{{z.newDoc}}</el-button></header>
    <div class="summary"><div><b>{{docs.length}}</b><small>{{z.mine}}</small></div><div><b>{{pending.length}}</b><small>{{z.toHandle}}</small></div><div><b>{{approved.length}}</b><small>{{z.approved}}</small></div><section><b>{{z.quick}}</b><el-button size="mini" @click="openDoc">{{z.notice}}</el-button><el-button size="mini" @click="fromType('leave')">{{z.leave}}</el-button><el-button size="mini" @click="fromType('reimbursement')">{{z.reimburse}}</el-button><el-button size="mini" @click="fromType('procurement')">{{z.procure}}</el-button></section></div>
    <el-tabs v-model="tab"><el-tab-pane :label="z.myDocs" name="docs"><el-table :data="docs" size="small" stripe><el-table-column :label="z.subject"><template slot-scope="{row}"><button class="link" @click="detail(row)">{{row.title}}</button></template></el-table-column><el-table-column :label="z.state" width="105"><template slot-scope="{row}"><el-tag size="mini" :type="tag(row.status)">{{state(row.status)}}</el-tag></template></el-table-column><el-table-column :label="z.action" width="130"><template slot-scope="{row}"><el-button v-if="row.status==='draft'" type="text" @click="submit(row)">{{z.submit}}</el-button><el-button v-if="row.status==='approved'" type="text" @click="publish(row)">{{z.publish}}</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane :label="z.approval" name="approval"><el-table :data="approvals" size="small"><el-table-column :label="z.subject"><template slot-scope="{row}"><button class="link" @click="approvalDetail(row)">{{row.title}}</button></template></el-table-column><el-table-column :label="z.action" width="160"><template slot-scope="{row}"><el-button v-if="row.can_handle" type="success" size="mini" @click="approve(row)">{{z.pass}}</el-button><el-button v-if="row.can_handle" type="danger" size="mini" @click="reject(row)">{{z.reject}}</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane :label="z.templates" name="templates"><div class="template-tip">{{z.templateHint}}</div><el-table :data="templates" size="small"><el-table-column prop="name" :label="z.templateName"/><el-table-column :label="z.action" width="110"><template slot-scope="{row}"><el-button type="text" @click="useTemplate(row)">{{z.use}}</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs>
  </main><el-dialog :title="z.docEdit" :visible.sync="docVisible" width="640px"><el-form :model="form" label-width="75px"><el-form-item :label="z.subject"><el-input v-model="form.title"/></el-form-item><el-form-item :label="z.content"><el-input v-model="form.content" type="textarea" :rows="10"/></el-form-item></el-form><span slot="footer"><el-button @click="docVisible=false">{{z.cancel}}</el-button><el-button type="primary" @click="saveDoc">{{z.save}}</el-button></span></el-dialog><el-dialog :title="z.detail" :visible.sync="detailVisible" width="640px"><pre>{{ content }}</pre></el-dialog></div>
</template>
<script>
import AppSidebar from '../components/Sidebar/index.vue'
const z={title:'\u516c\u6587\u5ba1\u6279',subtitle:'\u4e1a\u52a1\u7533\u8bf7\u3001\u9010\u7ea7\u5ba1\u6279\u3001\u516c\u6587\u6d41\u8f6c\u4e0e\u6a21\u677f\u590d\u7528',newDoc:'\u65b0\u5efa\u516c\u6587',mine:'\u6211\u53d1\u8d77\u7684',toHandle:'\u5f85\u6211\u5904\u7406',approved:'\u5df2\u901a\u8fc7',quick:'\u5feb\u6377\u53d1\u8d77',notice:'\u901a\u77e5',leave:'\u8bf7\u5047',reimburse:'\u62a5\u9500',procure:'\u91c7\u8d2d',myDocs:'\u6211\u7684\u516c\u6587',approval:'\u5f85\u6211\u5ba1\u6279',templates:'\u6a21\u677f\u5e93',subject:'\u4e8b\u9879',state:'\u72b6\u6001',action:'\u64cd\u4f5c',submit:'\u63d0\u4ea4\u5ba1\u6279',publish:'\u53d1\u5e03',pass:'\u901a\u8fc7',reject:'\u9a73\u56de',templateHint:'\u7cfb\u7edf\u6a21\u677f\u53ef\u76f4\u63a5\u751f\u6210\u516c\u6587\uff0c\u5305\u542b\u901a\u77e5\u3001\u8bf7\u5047\u3001\u62a5\u9500\u3001\u91c7\u8d2d\u3002',templateName:'\u6a21\u677f\u540d\u79f0',use:'\u4f7f\u7528',docEdit:'\u516c\u6587\u7f16\u8f91',content:'\u6b63\u6587',cancel:'\u53d6\u6d88',save:'\u4fdd\u5b58\u8349\u7a3f',detail:'\u516c\u6587\u8be6\u60c5'}
export default{components:{AppSidebar},data:()=>({z,tab:'docs',docVisible:false,detailVisible:false,current:null,form:{document_type:'notice'}}),computed:{ws(){return this.$store.getters['workspace/activeWorkspace']||{}},docs(){return this.$store.state.office.documents},approvals(){return this.$store.state.office.approvals},templates(){return this.$store.state.office.templates},pending(){return this.approvals.filter(x=>x.can_handle)},approved(){return this.docs.filter(x=>['approved','published'].includes(x.status))},content(){return this.current?this.current.content:''}},watch:{'ws.id':{immediate:true,handler(){this.load()}}},methods:{load(){if(this.ws.id&&this.ws.domain==='office')return Promise.all(['loadDocuments','loadApprovals','loadTemplates'].map(a=>this.$store.dispatch('office/'+a,this.ws.id)))},openDoc(){this.form={document_type:'notice'};this.docVisible=true},fromType(type){const x=this.templates.find(a=>a.document_type===type);this.form={title:x?x.name:'',content:x?x.content:'',document_type:type};this.docVisible=true},useTemplate(x){this.form={title:x.name,content:x.content,document_type:x.document_type};this.docVisible=true},async saveDoc(){await this.$store.dispatch('office/createDocument',{...this.form,workspace_id:this.ws.id});this.docVisible=false;this.load()},async submit(r){await this.$store.dispatch('office/submitDocument',{id:r.id,data:{},workspaceId:this.ws.id});this.load()},async publish(r){await this.$store.dispatch('office/publishDocument',{id:r.id,workspaceId:this.ws.id});this.load()},async detail(r){this.current=await this.$store.dispatch('office/getDocument',r.id);this.detailVisible=true},async approvalDetail(r){const x=await this.$store.dispatch('office/getApproval',r.id);this.current=x.document;this.detailVisible=true},async approve(r){await this.$store.dispatch('office/approve',{id:r.id,data:{},workspaceId:this.ws.id});this.load()},async reject(r){try{const x=await this.$prompt('\u8bf7\u586b\u5199\u9a73\u56de\u610f\u89c1','\u9a73\u56de\u5ba1\u6279');await this.$store.dispatch('office/reject',{id:r.id,data:{comment:x.value},workspaceId:this.ws.id});this.load()}catch(e){}},state(s){return({draft:'\u8349\u7a3f',reviewing:'\u5ba1\u6279\u4e2d',approved:'\u5df2\u6279\u51c6',published:'\u5df2\u53d1\u5e03',rejected:'\u5df2\u9a73\u56de'})[s]||s},tag(s){return({draft:'info',reviewing:'warning',approved:'success',published:'success',rejected:'danger'})[s]||''}}}
</script>
<style scoped>.office-page{display:flex;min-height:100vh;padding:12px;gap:12px;background:#f3f6fb}.main{flex:1;padding:18px;background:#fff;border-radius:12px}header{display:flex;justify-content:space-between;border-bottom:1px solid #edf0f5;padding-bottom:13px}h2{margin:0 0 4px}p,small{margin:0;color:#8492a6;font-size:13px}.summary{display:flex;gap:10px;margin:13px 0}.summary>div,.summary section{border:1px solid #e6edf5;border-radius:8px;padding:8px 12px;background:#fbfcff}.summary b,.summary small{display:block}.summary>div b{font-size:20px;color:#4088df}.summary section{flex:1}.summary section b{display:inline;margin-right:8px;font-size:12px}.link{border:0;background:none;color:#286fc0;cursor:pointer;font:inherit}.template-tip{padding:10px;background:#f3f8ff;color:#64748b;font-size:12px;margin-bottom:10px}pre{white-space:pre-wrap;line-height:1.7;background:#f7f9fc;padding:14px}@media(max-width:800px){.summary{flex-wrap:wrap}.summary section{min-width:100%}}</style>
